function generateRememberToken(userId) {
  const token = crypto.randomBytes(32).toString('base64url');
  rememberTokens.set(hashRememberToken(token), {
    userId,
    expiresAt: Date.now() + REMEMBER_TOKEN_TTL_MS,
  });
  return token;
}

function validateRememberToken(token) {
  const key = hashRememberToken(token);
  const entry = rememberTokens.get(key);
  if (!entry) return null;
  if (Date.now() > entry.expiresAt) {
    rememberTokens.delete(key);
    return null;
  }
  return entry.userId;
}

