test('generateRememberToken returns a url-safe token', () => {
  const token = generateRememberToken('u1');
  assert.ok(token.length > 0);
  assert.match(token, /^[A-Za-z0-9_-]+$/);
});

test('validateRememberToken accepts a token it issued', () => {
  const token = generateRememberToken('u1');
  assert.strictEqual(validateRememberToken(token), 'u1');
});

test('validateRememberToken rejects an unknown token', () => {
  assert.strictEqual(validateRememberToken('not-a-real-token'), null);
});

test('validateRememberToken rejects a tampered token', () => {
  const token = generateRememberToken('u1');
  const tampered = token.slice(0, -1) + (token.at(-1) === 'a' ? 'b' : 'a');
  assert.strictEqual(validateRememberToken(tampered), null);
});

test('validateRememberToken rejects an expired token', () => {
  const realNow = Date.now;
  try {
    Date.now = () => realNow() ;
    const token = generateRememberToken('u1');
    Date.now = () => realNow() + 31 * 24 * 60 * 60 * 1000; // 31 days later
    assert.strictEqual(validateRememberToken(token), null);
  } finally {
    Date.now = realNow;
  }
});

